    LLMConfig = apps.get_model("llm_connector", "LLMConfig")
    TransferConsent = apps.get_model("llm_connector", "TransferConsent")
    first = {}
    for user_id, at in LLMConfig.objects.filter(
        transfer_consent_at__isnull=False
    ).values_list("user_id", "transfer_consent_at"):
        first[user_id] = min(at, first.get(user_id, at))
    TransferConsent.objects.bulk_create(
        TransferConsent(user_id=u, scope="providers", given_at=at)
        for u, at in first.items()
    )


